function div(a,b){return ~~(a/b);}
function mod(a,b){return a-~~(a/b)*b;}
function jalCal(jy){var bk=[-61,9,38,199,426,686,756,818,1111,1181,1210,1635,2060,2097,2192,2262,2324,2394,2456,3178],bl=bk.length,gy=jy+621,leapJ=-14,jp=bk[0],jm,jump=0,leap,n,i;if(jy<jp||jy>=bk[bl-1])throw new Error('سال شمسی نامعتبر');for(i=1;i<bl;i++){jm=bk[i];jump=jm-jp;if(jy<jm)break;leapJ=leapJ+div(jump,33)*8+div(mod(jump,33),4);jp=jm;}n=jy-jp;leapJ=leapJ+div(n,33)*8+div(mod(n,33)+3,4);if(mod(jump,33)===4&&jump-n===4)leapJ+=1;var leapG=div(gy,4)-div((div(gy,100)+1)*3,4)-150,march=20+leapJ-leapG;if(jump-n<6)n=n-jump+div(jump+4,33)*33;leap=mod(mod(n+1,33)-1,4);if(leap===-1)leap=4;return{leap:leap,gy:gy,march:march};}
function g2d(gy,gm,gd){var d=div((gy+div(gm-8,6)+100100)*1461,4)+div(153*mod(gm+9,12)+2,5)+gd-34840408;d=d-div(div(gy+100100+div(gm-8,6),100)*3,4)+752;return d;}
function d2g(jdn){var j=4*jdn+139361631;j=j+div(div(4*jdn+183187720,146097)*3,4)*4-3908;var i=div(mod(j,1461),4)*5+308,gd=div(mod(i,153),5)+1,gm=mod(div(i,153),12)+1,gy=div(j,1461)-100100+div(8-gm,6);return{gy:gy,gm:gm,gd:gd};}
function d2j(jdn){var gy=d2g(jdn).gy,jy=gy-621,r=jalCal(jy),jdn1f=g2d(gy,3,r.march),k=jdn-jdn1f,jm,jd;if(k>=0){if(k<=185){jm=1+div(k,31);jd=mod(k,31)+1;return{jy:jy,jm:jm,jd:jd};}k-=186;}else{jy-=1;k+=179;if(r.leap===1)k+=1;}jm=7+div(k,30);jd=mod(k,30)+1;return{jy:jy,jm:jm,jd:jd};}
function pad(n){return String(n).length<2?'0'+n:String(n);}
function toJ(iso){var p=String(iso).slice(0,10).split('-');return d2j(g2d(+p[0],+p[1],+p[2]));}
function jLen(jy,jm){if(jm<=6)return 31;if(jm<=11)return 30;return jalCal(jy).leap===0?30:29;}

let isScheduled = false;
try { isScheduled = !!$('بررسی روزانه ساعت ۲۳:۴۵').first(); } catch (e) { isScheduled = false; }

const todayISO = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Tehran' });
const t = toJ(todayISO);
const isLastDay = t.jd === jLen(t.jy, t.jm);

const closesQuarter = isLastDay && (t.jm === 3 || t.jm === 6 || t.jm === 9 || t.jm === 12);
const shouldRun = !isScheduled || closesQuarter;

const DEFS = [
  ['سه‌ماهه', 'Q1', 1, 3], ['سه‌ماهه', 'Q2', 4, 6], ['سه‌ماهه', 'Q3', 7, 9], ['سه‌ماهه', 'Q4', 10, 12],
  ['شش‌ماهه', 'H1', 1, 6], ['شش‌ماهه', 'H2', 7, 12],
  ['سالانه', 'Y', 1, 12],
];

const lastCompleteMonth = isLastDay ? t.jm : t.jm - 1;

const periods = [];
[t.jy - 1, t.jy].forEach(function (jy) {
  const limit = jy < t.jy ? 12 : lastCompleteMonth;
  DEFS.forEach(function (d) {
    if (d[3] <= limit) {
      periods.push({ type: d[0], code: d[1], jy: jy, fromM: d[2], toM: d[3], id: jy + '-' + d[1] });
    }
  });
});

return [{
  json: {
    shouldRun: shouldRun,
    shouldEmail: !isScheduled || closesQuarter,
    isScheduled: isScheduled,
    todayISO: todayISO,
    todayShamsi: t.jy + '/' + pad(t.jm) + '/' + pad(t.jd),
    jy: t.jy,
    jm: t.jm,
    periods: periods,
    reason: shouldRun ? 'دوره‌های کامل‌شده بازمحاسبه می‌شوند' : 'امروز پایان فصل نیست',
  },
}];

function toNum(v){var s=String(v==null?'':v).replace(/[۰-۹]/g,function(d){return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d);}).replace(/[^0-9.\-]/g,'');var n=Number(s);return Number.isFinite(n)?n:0;}
function rows(name){ try { return $(name).all().map(function(i){return i.json||{};}); } catch(e) { return []; } }
function priceOf(name, sym){ try { const p=$(name).first().json; const v=p&&p.data&&p.data.prices&&p.data.prices[sym]?p.data.prices[sym].current:null; return toNum(v);} catch(e){ return 0; } }

const ctl = $('تعیین دوره‌های سررسید').first().json;

const settings = {};
rows('تنظیمات').forEach(function (r) { if (r['کلید']) settings[String(r['کلید']).trim()] = r['مقدار']; });
const basis = String(settings['مبنای_تعدیل_سرمایه'] || 'طلا').trim();
const reportEmail = String(settings['ایمیل_گزارش'] || 'f.shams.apg@gmail.com');
const schoolName = String(settings['نام_آموزشگاه'] || 'آموزشگاه علمی فردا');

const monthly = rows('گزارش ماهانه').filter(function (r) { return r['شناسه_دوره']; });
const capital = rows('آورده سرمایه').filter(function (r) { return r['شناسه']; });
const idx = {};
rows('شاخص سالانه').forEach(function (r) {
  const y = toNum(r['سال_شمسی']);
  if (y) idx[y] = toNum(r['نرخ_تورم_رسمی_درصد']);
});

const goldToday = priceOf('نرخ طلا امروز', 'GOLD18K');
const usdToday = priceOf('نرخ دلار امروز', 'USD');

const now = new Date().toISOString();

function aggregate(jy, fromM, toM) {
  const sel = monthly.filter(function (r) {
    const y = toNum(r['سال_شمسی']);
    const m = toNum(r['ماه_شمسی']);
    return y === jy && m >= fromM && m <= toM;
  });
  const acc = { income: 0, expense: 0, payroll: 0, profit: 0, capital: 0, months: sel.length };
  sel.forEach(function (r) {
    acc.income += toNum(r['جمع_درآمد']);
    acc.expense += toNum(r['جمع_هزینه']);
    acc.payroll += toNum(r['حقوق_مدرسین']);
    acc.profit += toNum(r['سود_عملیاتی']);
    acc.capital += toNum(r['آورده_سرمایه_گذار']);
  });
  return acc;
}

function previousOf(p) {
  if (p.code === 'Y') return { jy: p.jy - 1, fromM: 1, toM: 12 };
  if (p.code === 'H1') return { jy: p.jy - 1, fromM: 7, toM: 12 };
  if (p.code === 'H2') return { jy: p.jy, fromM: 1, toM: 6 };
  if (p.code === 'Q1') return { jy: p.jy - 1, fromM: 10, toM: 12 };
  if (p.code === 'Q2') return { jy: p.jy, fromM: 1, toM: 3 };
  if (p.code === 'Q3') return { jy: p.jy, fromM: 4, toM: 6 };
  return { jy: p.jy, fromM: 7, toM: 9 };
}

const periodRows = [];
(ctl.periods || []).forEach(function (p) {
  const a = aggregate(p.jy, p.fromM, p.toM);
  if (a.months === 0) return;
  const prevDef = previousOf(p);
  const prev = aggregate(prevDef.jy, prevDef.fromM, prevDef.toM);
  const growth = prev.profit !== 0 ? Math.round((a.profit - prev.profit) / Math.abs(prev.profit) * 1000) / 10 : '';
  periodRows.push({
    'نوع_دوره': p.type,
    'شناسه_دوره': p.id,
    'سال_شمسی': p.jy,
    'از_ماه': p.fromM,
    'تا_ماه': p.toM,
    'جمع_درآمد': a.income,
    'جمع_هزینه': a.expense,
    'حقوق_مدرسین': a.payroll,
    'سود': a.profit,
    'حاشیه_سود_درصد': a.income > 0 ? Math.round(a.profit / a.income * 1000) / 10 : 0,
    'میانگین_سود_ماهانه': a.months > 0 ? Math.round(a.profit / a.months) : 0,
    'رشد_نسبت_به_دوره_قبل_درصد': growth,
    'آورده_سرمایه_دوره': a.capital,
    'تاریخ_تولید': now,
  });
});

function inflate(amount, fromYear) {
  let v = amount;
  for (let y = fromYear; y < ctl.jy; y++) {
    const rate = idx[y];
    if (rate && rate > 0) v = v * (1 + rate / 100);
  }
  return Math.round(v);
}

const byInvestor = {};
capital.forEach(function (r) {
  const code = String(r['کد_سرمایه_گذار'] || 'نامشخص');
  if (!byInvestor[code]) {
    byInvestor[code] = { name: r['نام_سرمایه_گذار'] || code, nominal: 0, grams: 0, usd: 0, goldValue: 0, usdValue: 0, cpiValue: 0 };
  }
  const b = byInvestor[code];
  const amount = toNum(r['مبلغ_تومان']);
  const grams = toNum(r['معادل_گرم_طلا']);
  const usd = toNum(r['معادل_دلار']);
  const year = toNum(r['سال_شمسی']) || ctl.jy;
  const cpi = inflate(amount, year);
  b.nominal += amount;
  b.grams += grams;
  b.usd += usd;
  b.cpiValue += cpi;
  b.goldValue += (grams > 0 && goldToday > 0) ? Math.round(grams * goldToday) : cpi;
  b.usdValue += (usd > 0 && usdToday > 0) ? Math.round(usd * usdToday) : cpi;
});

const codes = Object.keys(byInvestor);
function pickValue(b) {
  if (basis === 'دلار') return b.usdValue;
  if (basis.indexOf('تورم') >= 0) return b.cpiValue;
  return b.goldValue;
}
let totalBasis = 0;
codes.forEach(function (c) { totalBasis += pickValue(byInvestor[c]); });

const equityRows = codes.map(function (c) {
  const b = byInvestor[c];
  const value = pickValue(b);
  return {
    'تاریخ_محاسبه': now,
    'سال_شمسی': ctl.jy,
    'کد_سرمایه_گذار': c,
    'نام_سرمایه_گذار': b.name,
    'جمع_آورده_اسمی': b.nominal,
    'معادل_گرم_طلا': Math.round(b.grams * 10000) / 10000,
    'معادل_دلار': Math.round(b.usd * 100) / 100,
    'نرخ_طلای18_امروز': goldToday || '',
    'نرخ_دلار_امروز': usdToday || '',
    'ارزش_روز_طلایی': b.goldValue,
    'ارزش_روز_دلاری': b.usdValue,
    'ارزش_روز_تورمی': b.cpiValue,
    'سود_تورمی_تحقق_نیافته': value - b.nominal,
    'درصد_از_کل_سرمایه': totalBasis > 0 ? Math.round(value / totalBasis * 1000) / 10 : 0,
  };
});
equityRows.sort(function (a, b) { return b['جمع_آورده_اسمی'] - a['جمع_آورده_اسمی']; });

return [{
  json: {
    ctl: ctl,
    basis: basis,
    reportEmail: reportEmail,
    schoolName: schoolName,
    goldToday: goldToday,
    usdToday: usdToday,
    periodRows: periodRows,
    equityRows: equityRows,
  },
}];

const d = $input.first().json;
const SHEET_URL = 'https://docs.google.com/spreadsheets/d/12j12zy8lqxlft1mBIZ0THmG-Ro24TZmUqijVwMpuTg4/edit';
const MONTHS = ['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];

function money(n) { return Math.round(Number(n) || 0).toLocaleString('en-US'); }
function pctCell(v) {
  if (v === '' || v === null || v === undefined) return '<td style="color:#9aa0a6">—</td>';
  const c = Number(v) >= 0 ? '#137333' : '#c5221f';
  return '<td style="color:' + c + '"><b>' + v + '٪</b></td>';
}

const periods = d.periodRows || [];
const equity = d.equityRows || [];
const cy = d.ctl.jy;

const current = periods.filter(function (p) { return p['سال_شمسی'] === cy; });
const rowsHtml = current.map(function (p) {
  return '<tr>'
    + '<td>' + p['نوع_دوره'] + ' (' + MONTHS[p['از_ماه'] - 1] + ' تا ' + MONTHS[p['تا_ماه'] - 1] + ')</td>'
    + '<td>' + money(p['جمع_درآمد']) + '</td>'
    + '<td>' + money(p['جمع_هزینه']) + '</td>'
    + '<td><b>' + money(p['سود']) + '</b></td>'
    + '<td>' + p['حاشیه_سود_درصد'] + '٪</td>'
    + '<td>' + money(p['میانگین_سود_ماهانه']) + '</td>'
    + pctCell(p['رشد_نسبت_به_دوره_قبل_درصد'])
    + '</tr>';
}).join('');

const equityHtml = equity.map(function (e) {
  const gain = e['سود_تورمی_تحقق_نیافته'];
  const c = gain >= 0 ? '#137333' : '#c5221f';
  return '<tr>'
    + '<td>' + e['نام_سرمایه_گذار'] + '</td>'
    + '<td>' + money(e['جمع_آورده_اسمی']) + '</td>'
    + '<td>' + e['معادل_گرم_طلا'] + '</td>'
    + '<td>' + money(e['ارزش_روز_طلایی']) + '</td>'
    + '<td>' + money(e['ارزش_روز_دلاری']) + '</td>'
    + '<td>' + money(e['ارزش_روز_تورمی']) + '</td>'
    + '<td style="color:' + c + '"><b>' + money(gain) + '</b></td>'
    + '<td>' + e['درصد_از_کل_سرمایه'] + '٪</td>'
    + '</tr>';
}).join('');

let nominalSum = 0, basisSum = 0;
equity.forEach(function (e) {
  nominalSum += Number(e['جمع_آورده_اسمی']) || 0;
  basisSum += Number(d.basis === 'دلار' ? e['ارزش_روز_دلاری'] : (String(d.basis).indexOf('تورم') >= 0 ? e['ارزش_روز_تورمی'] : e['ارزش_روز_طلایی'])) || 0;
});

const rateNote = d.goldToday
  ? 'نرخ مبنا: طلای ۱۸ عیار ' + money(d.goldToday) + ' تومان — دلار ' + money(d.usdToday) + ' تومان'
  : 'نرخ لحظه‌ای در دسترس نبود؛ محاسبه بر پایه تورم رسمی شیت «شاخص_سالانه» انجام شد.';

const html = '<div dir="rtl" style="font-family:Tahoma,Arial,sans-serif;font-size:14px;color:#202124;max-width:860px">'
  + '<h2 style="margin:0 0 4px">گزارش دوره‌ای سال ' + cy + '</h2>'
  + '<div style="color:#5f6368;margin-bottom:16px">' + d.schoolName + ' — تا تاریخ ' + d.ctl.todayShamsi + ' — مبالغ به تومان</div>'
  + '<h3 style="margin:18px 0 6px">سود و زیان دوره‌ای</h3>'
  + (current.length
    ? '<table border="1" cellpadding="7" style="border-collapse:collapse;border-color:#dadce0;width:100%">'
      + '<tr style="background:#f1f3f4"><th align="right">دوره</th><th align="right">درآمد</th><th align="right">هزینه</th><th align="right">سود</th><th>حاشیه</th><th align="right">میانگین ماهانه</th><th>رشد</th></tr>'
      + rowsHtml + '</table>'
    : '<div style="color:#5f6368">هنوز دوره کاملی در سال ' + cy + ' بسته نشده است.</div>')
  + '<h3 style="margin:22px 0 6px">ارزش امروزِ سرمایه‌گذاران</h3>'
  + '<div style="color:#5f6368;font-size:12px;margin-bottom:8px">مبنای انتخابی شما: <b>' + d.basis + '</b> — ' + rateNote + '</div>'
  + (equity.length
    ? '<table border="1" cellpadding="7" style="border-collapse:collapse;border-color:#dadce0;width:100%">'
      + '<tr style="background:#f1f3f4"><th align="right">سرمایه‌گذار</th><th align="right">آورده اسمی</th><th>گرم طلا</th><th align="right">ارزش طلایی</th><th align="right">ارزش دلاری</th><th align="right">ارزش تورمی</th><th align="right">رشد ارزش</th><th>سهم</th></tr>'
      + equityHtml
      + '<tr style="background:#f8f9fa"><td><b>جمع</b></td><td><b>' + money(nominalSum) + '</b></td><td></td><td colspan="3"><b>' + money(basisSum) + '</b> (مبنای ' + d.basis + ')</td><td><b>' + money(basisSum - nominalSum) + '</b></td><td></td></tr>'
      + '</table>'
    : '<div style="color:#5f6368">هنوز آورده‌ای در شیت «آورده_سرمایه» ثبت نشده است.</div>')
  + '<div style="background:#fef7e0;padding:12px;border-radius:8px;margin-top:14px;font-size:13px">'
  + 'ستون «رشد ارزش» یعنی اگر همان پول در تاریخ آورده به طلا/دلار تبدیل شده بود، امروز چقدر می‌ارزید. '
  + 'این عدد <b>بدهی ثبت‌شده نیست</b> — فقط نشان می‌دهد سرمایه‌گذارها از نظر قدرت خرید کجا ایستاده‌اند.'
  + '</div>'
  + '<p><a href="' + SHEET_URL + '" style="background:#1a73e8;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;display:inline-block">باز کردن دفتر حسابداری</a></p>'
  + '</div>';

return [{
  json: {
    shouldEmail: d.ctl.shouldEmail,
    reportEmail: d.reportEmail,
    subject: 'گزارش دوره‌ای و ارزش سرمایه — ' + d.schoolName + ' (' + d.ctl.todayShamsi + ')',
    html: html,
  },
}];
